class Main {
    public static void main(String[] args) {
        // 공백 없는 문자열 하나를 읽어요.
        var scanner = new java.util.Scanner(System.in, "UTF-8");
        String word = scanner.next();
        // 문자열 내용은 equals로 비교해요.
        if (word.equals("java")) {
            System.out.println("환영해요");
        } else {
            System.out.println("다시 입력해요");
        }
    }
}
